package com.pharmapack.qms.aql; import jakarta.persistence.*; import lombok.*; import java.math.*; @Entity @Table(name="aql_plans") @Getter @Setter @NoArgsConstructor public class AqlPlan { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="plan_code",nullable=false,unique=true) String planCode; String inspectionLevel; BigDecimal aqlValue; Integer sampleSize,acceptanceNumber,rejectionNumber; String description; }
